import re


_VERSION_RE = re.compile(r"^[0-9]+\.[0-9]+\.[0-9]+$")
_COMPARATOR_RE = re.compile(r"^(>=|<=|>|<|=)([0-9]+\.[0-9]+\.[0-9]+)$")


def satisfies(version: str, spec: str) -> bool:
    def parse_version(value: str) -> tuple[int, int, int]:
        if not isinstance(value, str) or not _VERSION_RE.fullmatch(value):
            raise ValueError(f"Malformed version: {value!r}")
        return tuple(int(part) for part in value.split("."))

    if not isinstance(spec, str):
        raise ValueError(f"Malformed spec: {spec!r}")

    version_tuple = parse_version(version)
    spec = spec.strip()

    if not spec:
        raise ValueError("Malformed spec")

    # Exact version
    if _VERSION_RE.fullmatch(spec):
        return version_tuple == parse_version(spec)

    # Caret range
    if spec.startswith("^"):
        base = parse_version(spec[1:])
        major, minor, patch = base

        if major > 0:
            upper = (major + 1, 0, 0)
        elif minor > 0:
            upper = (0, minor + 1, 0)
        else:
            upper = (0, 0, patch + 1)

        return base <= version_tuple < upper

    # Tilde range
    if spec.startswith("~"):
        base = parse_version(spec[1:])
        upper = (base[0], base[1] + 1, 0)
        return base <= version_tuple < upper

    # Space-separated conjunction of comparators
    tokens = spec.split()
    if not tokens:
        raise ValueError("Malformed spec")

    for token in tokens:
        match = _COMPARATOR_RE.fullmatch(token)
        if not match:
            raise ValueError(f"Malformed spec: {spec!r}")

        operator, operand_text = match.groups()
        operand = parse_version(operand_text)

        if operator == ">=" and not (version_tuple >= operand):
            return False
        if operator == ">" and not (version_tuple > operand):
            return False
        if operator == "<=" and not (version_tuple <= operand):
            return False
        if operator == "<" and not (version_tuple < operand):
            return False
        if operator == "=" and not (version_tuple == operand):
            return False

    return True
